#!/usr/bin/env node
/**
 * Deterministic, idempotent seed for the EBPS ERP.
 *
 * Creates the full reference chain the API needs to return meaningful data:
 * school, branches, academic year/terms, grades, sections/classes, subjects,
 * departments, staff (+ roles), students, attendance, fees, invoices,
 * payments, library, transport, hostel, announcements, events, inventory.
 *
 * Re-running is safe: every write is `onConflictDoNothing`.
 * Run with: npx tsx --env-file=.env.local scripts/seed.ts
 */

import { drizzle } from 'drizzle-orm/node-postgres'
import type { InferSelectModel } from 'drizzle-orm'
import { createHash } from 'node:crypto'
import { Pool } from 'pg'
import * as schema from '../lib/db/schema.ts'

const pool = new Pool({ connectionString: process.env.DATABASE_URL })
const db = drizzle(pool, { schema })

const SCHOOL_ID = 'emam-bukhari-private-school'
const ACADEMIC_YEAR_ID = 'ay-1403'

/** Deterministic UUID for a readable slug so re-seeds stay idempotent. */
function deterministicUuid(seed: string): string {
  const hex = createHash('sha1').update(seed).digest('hex')
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-5${hex.slice(13, 16)}-a${hex.slice(17, 20)}-${hex.slice(20, 32)}`
}

